mapper.select:
SELECT * FROM history
WHERE conversation_id = #{conversationId}
ORDER BY id ASC

SELECT * FROM (
    SELECT * FROM history
    WHERE conversation_id = #{conversationId}
    ORDER BY id DESC
    LIMIT #{limit}
) t ORDER BY t.id ASC

SELECT IFNULL(SUM(token_count),0)
FROM history
WHERE conversation_id = #{conversationId}

mapper.delete:
DELETE FROM history
WHERE id IN (
SELECT id FROM (
SELECT id FROM history
WHERE conversation_id = #{conversationId}
ORDER BY id ASC
LIMIT #{limit}
) t
)
